{
  "name": "@squish/cli",
  "version": "1.7.0",
  "description": "Squish CLI - Universal Memory for AI Agents",
  "type": "module",
  "main": "src/index.ts",
  "bin": {
    "squish": "../bin/squish.mjs"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch"
  },
  "dependencies": {
    "commander": "^12.0.0",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^6.0.2"
  }
}

{
  "name": "@squish/mcp",
  "version": "1.9.0",
  "description": "Squish MCP Server - Model Context Protocol Server",
  "type": "module",
  "main": "src/index.ts",
  "bin": {
    "squish-mcp": "../../bin/squish-mcp.mjs"
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "start": "tsx src/index.ts",
    "mcp:stdio": "tsx src/index.ts --stdio",
    "mcp:http": "tsx src/index.ts --http"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.27.1",
    "zod": "^3.24.0",
    "express": "^5.2.1"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "typescript": "^6.0.2"
  }
}

{
  "id": "squish-memory",
  "name": "Squish Memory",
  "description": "Persistent memory for AI agents with auto-capture and context injection",
  "kind": "memory",
  "configSchema": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "dataDir": {
        "type": "string",
        "description": "Path to Squish data directory",
        "default": "~/.squish"
      },
      "autoCapture": {
        "type": "boolean",
        "description": "Auto-capture tool results",
        "default": true
      },
      "contextLimit": {
        "type": "number",
        "description": "Number of memories to inject on session start",
        "default": 5
      }
    }
  },
  "activation": {
    "onStartup": true
  },
  "contracts": {
    "tools": ["squish_remember", "squish_recall", "squish_context", "squish_stats", "squish_forget", "squish_inspect"]
  }
}

{
  "name": "@squish-memory/openclaw-plugin",
  "version": "1.9.0",
  "description": "Squish Memory plugin for OpenClaw - uses the installed squish CLI for memory actions",
  "type": "module",
  "main": "dist/index.js",
  "openclaw": {
    "extensions": ["./dist/index.js"],
    "compat": {
      "pluginApi": ">=2026.3.24-beta.2",
      "minGatewayVersion": "2026.3.24-beta.2"
    },
    "build": {
      "openclawVersion": "2026.5.17",
      "pluginSdkVersion": "2026.5.17"
    }
  }
}

{
  "name": "@squish-memory/opencode-plugin",
  "version": "1.9.0",
  "description": "Squish Memory plugin for OpenCode - thin wrapper over the squish sessions CLI (capture, search, list, show, related, inject) plus auto-capture lifecycle hooks",
  "type": "module",
  "main": "index.ts",
  "files": [
    "index.ts",
    "commands/",
    "README.md"
  ],
  "dependencies": {
    "zod": "^4.3.6"
  }
}
